float hash(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);float a=hash(i),b=hash(i+vec2(1,0)),c=hash(i+vec2(0,1)),d=hash(i+vec2(1,1));return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);}
float fbm(vec2 p){float v=0.0,a=0.5;for(int i=0;i<4;i++){v+=a*noise(p);p=p*2.03+vec2(1.7,9.2);a*=0.5;}return v;}
mat2 rot(float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c);}
vec2 el(vec2 p,vec2 c,vec2 r,float ang){return (rot(ang)*(p-c))/r;}

vec4 kiwiHalf(vec2 p,vec2 c,vec2 r,float ang,vec2 skinOff,vec3 L,float sid,vec3 warm){
  vec2 es=el(p,c+skinOff,r*1.05,ang);
  float ls=length(es)+0.03*(fbm(p*0.08)-0.5);
  float aS=1.0-smoothstep(0.96,1.0,ls);
  vec3 skin=mix(vec3(0.8,0.52,0.2),vec3(0.42,0.22,0.07),smoothstep(0.55,1.0,ls));
  skin*=0.8+0.35*noise(p*0.3);
  vec3 Lr=vec3(rot(ang)*L.xy,L.z);
  vec3 ns=vec3(es,sqrt(max(0.0,1.0-dot(es,es))));
  skin*=0.6+0.5*max(dot(ns,Lr),0.0);
  vec2 e=el(p,c,r,ang);
  float le=length(e)+0.02*(noise(p*0.15)-0.5);
  float aF=1.0-smoothstep(0.95,0.99,le);
  float an=atan(e.y,e.x);
  float fib=noise(vec2(an*28.0,le*5.0+sid));
  vec3 g=mix(vec3(0.45,0.78,0.22),vec3(0.08,0.38,0.1),smoothstep(0.42,0.95,le));
  g*=0.82+0.35*fib;
  g=mix(g,vec3(0.55,0.66,0.2),smoothstep(0.88,0.97,le)*0.6);
  float cw=0.26+0.06*(fib-0.5);
  g=mix(g,vec3(0.95,0.96,0.86),1.0-smoothstep(cw-0.05,cw+0.02,le));
  float seed=0.0;
  for(int i=0;i<2;i++){
    float N=(i==0)?32.0:26.0;
    float s=an/6.28318*N+float(i)*0.5;
    float id=floor(s);float fs=fract(s)-0.5;
    float h=hash(vec2(id+sid*13.0,float(i)+2.0));
    float rr=((i==0)?0.39:0.46)+0.05*(h-0.5);
    float tg=fs*6.28318/N*le;
    float rd=le-rr;
    float m=length(vec2(tg/0.016,rd/0.035));
    seed=max(seed,(1.0-smoothstep(0.7,1.0,m))*step(0.25,h));
  }
  g=mix(g,vec3(0.07,0.05,0.03),seed);
  vec3 n=normalize(vec3(e*0.55,1.0));
  float diff=max(dot(n,Lr),0.0);
  vec3 H=normalize(Lr+vec3(0,0,1));
  float nh=max(dot(n,H),0.0);
  float spec=pow(nh,90.0)*0.9+pow(nh,14.0)*0.18;
  spec*=0.6+0.6*fib;
  vec3 fl=g*(0.7+0.45*diff)+warm*spec*(1.0-seed);
  vec2 cell=floor(p/5.0);float hh=hash(cell+sid);
  vec2 f=fract(p/5.0)-0.5;
  float tw=pow(0.5+0.5*sin(iTime*4.0+hh*40.0),12.0);
  float sp=step(0.86,hh)*smoothstep(0.3,0.0,length(f))*tw*smoothstep(0.92,0.5,le)*(1.0-seed);
  fl+=vec3(1.0,0.97,0.88)*sp*(0.6+1.5*pow(nh,6.0));
  vec3 col=mix(skin,fl,aF);
  return vec4(col,max(aS,aF));
}

void mainImage(out vec4 fragColor,in vec2 fragCoord){
  vec2 q=(fragCoord-0.5*iResolution.xy)/iResolution.y;
  vec2 p=vec2(450.0+q.x*560.0,275.0-q.y*560.0);
  float t=iTime;
  float lx=sin(t*0.5);
  vec3 L=normalize(vec3(lx*1.1,-0.6,0.8));
  vec3 warm=vec3(1.0,0.84,0.6);
  vec3 col=vec3(0.91,0.90,0.87)*(0.97+0.04*noise(p*0.7));
  float w=fbm(p*0.03);
  float topY=173.0-0.015*(p.x-65.0)+8.0*(w-0.5)+5.0*sin(p.x*0.03);
  float botY=458.0-0.02*(p.x-80.0)+6.0*(w-0.5);
  float leftX=66.0+0.04*(p.y-175.0)+6.0*(w-0.5);
  float rightX=772.0+(p.y-165.0)*0.25+8.0*(w-0.5);
  float dT=p.y-topY,dB=botY-p.y,dL=p.x-leftX,dR=rightX-p.x;
  float d=min(min(dT,dB),min(dL,dR));
  float ps=smoothstep(18.0,0.0,p.y-botY)*step(0.0,p.y-botY)*step(leftX,p.x)*step(p.x,rightX+10.0);
  col=mix(col,vec3(0.72,0.75,0.8),ps*0.5);
  vec3 cc=vec3(0.96,0.96,0.95);
  float st=fbm(vec2(p.x*0.012+p.y*0.006,p.y*0.035));
  cc-=vec3(0.10,0.09,0.06)*smoothstep(0.5,0.75,st);
  float st2=fbm(vec2(p.x*0.03-p.y*0.02,p.y*0.01+3.0));
  cc-=0.06*smoothstep(0.55,0.8,st2);
  cc=mix(cc,vec3(0.72,0.76,0.82),smoothstep(25.0,0.0,dB)*0.7);
  cc=mix(cc,vec3(0.78,0.8,0.85),smoothstep(20.0,0.0,dR)*0.5);
  cc=mix(cc,vec3(0.8,0.82,0.86),smoothstep(14.0,0.0,dL)*0.45);
  vec2 so=vec2(-lx*45.0,22.0);
  float sh=0.0;
  sh=max(sh,1.0-smoothstep(0.2,1.0,length((p-vec2(345.0,255.0)-so)/vec2(125.0,70.0))));
  sh=max(sh,1.0-smoothstep(0.2,1.0,length((p-vec2(545.0,265.0)-so)/vec2(100.0,55.0))));
  sh=max(sh,1.0-smoothstep(0.2,1.0,length((p-vec2(485.0,345.0)-so)/vec2(80.0,45.0))));
  sh=max(sh,1.0-smoothstep(0.2,1.0,length((p-vec2(370.0,375.0)-so)/vec2(95.0,40.0))));
  sh=max(sh,0.45*(1.0-smoothstep(0.3,1.0,length((p-vec2(450.0,320.0)-so*0.6)/vec2(270.0,125.0)))));
  cc=mix(cc,cc*vec3(0.74,0.74,0.8),sh*0.65);
  col=mix(col,cc,smoothstep(0.0,2.0,d));
  {
    vec2 e=el(p,vec2(535.0,228.0),vec2(90.0,68.0),0.45);
    float le=length(e)+0.06*(noise(p*0.5)-0.5);
    float a=1.0-smoothstep(0.95,1.0,le);
    vec3 n=vec3(e,sqrt(max(0.0,1.0-dot(e,e))));
    vec3 Lr=vec3(rot(0.45)*L.xy,L.z);
    float diff=max(dot(n,Lr),0.0);
    vec3 kc=mix(vec3(0.64,0.4,0.14),vec3(0.4,0.2,0.07),noise(p*0.35));
    kc=mix(kc,vec3(0.78,0.58,0.26),smoothstep(0.6,0.9,noise(p*0.9))*0.5);
    kc=mix(kc,vec3(0.18,0.09,0.03),1.0-smoothstep(0.0,0.12,length(e-vec2(0.82,0.05))));
    kc*=0.35+0.85*diff;
    kc+=warm*0.15*pow(max(dot(n,normalize(Lr+vec3(0,0,1))),0.0),8.0);
    col=mix(col,kc,a);
  }
  {
    vec2 e=(p-vec2(343.0,214.0))/vec2(102.0,86.0);
    float le=length(e)+0.02*(noise(p*0.2)-0.5);
    float a=1.0-smoothstep(0.97,1.0,le);
    vec3 n=vec3(e,sqrt(max(0.0,1.0-dot(e,e))));
    float diff=max(dot(n,L),0.0);
    float streak=fbm(vec2(atan(e.x,-(e.y+0.55))*6.0,length(e+vec2(0.0,0.55))*2.0));
    float ym=smoothstep(0.35,-0.55,e.x*0.7+e.y*0.7);
    vec3 red=vec3(0.8,0.12,0.08),yel=vec3(0.96,0.78,0.22),dk=vec3(0.42,0.05,0.05);
    vec3 ac=mix(red,yel,clamp(ym*(0.4+1.0*streak),0.0,1.0));
    ac=mix(ac,dk,smoothstep(0.1,1.0,e.y*0.8+e.x*0.25+0.3*streak)*0.8);
    float ds=length((e-vec2(0.02,-0.52))*vec2(1.0,1.6));
    ac=mix(ac,vec3(0.5,0.4,0.12),smoothstep(0.16,0.05,ds)*0.8);
    ac=mix(ac,vec3(0.15,0.1,0.05),smoothstep(0.05,0.02,ds));
    ac*=0.38+0.8*diff;
    vec3 H=normalize(L+vec3(0,0,1));
    float nh=max(dot(n,H),0.0);
    ac+=warm*(pow(nh,40.0)*0.7+pow(nh,6.0)*0.12);
    col=mix(col,ac,a);
  }
  vec4 k1=kiwiHalf(p,vec2(482.0,283.0),vec2(58.0,76.0),0.35,vec2(10.0,9.0),L,1.0,warm);
  col=mix(col,k1.rgb,k1.a);
  vec4 k2=kiwiHalf(p,vec2(360.0,333.0),vec2(76.0,55.0),-0.12,vec2(9.0,8.0),L,2.0,warm);
  col=mix(col,k2.rgb,k2.a);
  float pool=exp(-pow(length((p-vec2(450.0+320.0*lx,240.0))/vec2(340.0,240.0)),2.0));
  col*=mix(vec3(0.92,0.93,0.98),vec3(1.07,1.01,0.9),pool);
  col*=0.97+0.03*noise(p*1.3);
  col*=1.0-0.15*pow(length(q*vec2(0.8,1.0)),2.0);
  fragColor=vec4(clamp(col,0.0,1.0),1.0);
}
